//! An SSH server with an SFTP subsystem, for tests.
//!
//! There is no SSH daemon on a typical Windows machine, and asking anyone
//! running this suite to install and configure one is not reasonable. So the
//! suite brings its own: it serves the same generated byte sequence every
//! other mock in this project serves, which means a file fetched over SFTP
//! can be checked against the identical expectation as one fetched over
//! HTTP or FTP.
//!
//! Only what a download needs is implemented — `realpath`, `stat`, `open`,
//! `read`, `close`. Everything else answers "unsupported", which is also a
//! useful property: a client that depended on more would fail here rather
//! than in front of a real server.
//!
//!   stub-sftp-server --port 2222 [--host-key <path>]
//!
//! The host key is written to the given path on startup so a test can put
//! it in a `known_hosts` file and exercise key checking rather than skip it.

use std::collections::HashMap;
use std::sync::Arc;

use russh::keys::PrivateKey;
use russh::server::{Auth, Msg, Server as _, Session};
use russh::{Channel, ChannelId, MethodSet};
use russh_sftp::protocol::{
    Attrs, Data, File, FileAttributes, Handle, Name, OpenFlags, Status, StatusCode, Version,
};

/// The server's host key. Fixed on purpose; see where it is loaded.
const HOST_KEY: &str = "-----BEGIN OPENSSH PRIVATE KEY-----\nb3BlbnNzaC1rZXktdjEAAAAABG5vbmUAAAAEbm9uZQAAAAAAAAABAAAAMwAAAAtzc2gtZW\nQyNTUxOQAAACCVAzmnqxD7BDhsC5rF+Hh99I1LJjGvA1B8DrLSW4jGaAAAAKBJy4uFScuL\nhQAAAAtzc2gtZWQyNTUxOQAAACCVAzmnqxD7BDhsC5rF+Hh99I1LJjGvA1B8DrLSW4jGaA\nAAAECcUSVlY5ziMCzP46lJSNgtSu5seh7qdQz9rZ7USeiksJUDOaerEPsEOGwLmsX4eH30\njUsmMa8DUHwOstJbiMZoAAAAFmRpdmluZS1pZG0tdGVzdC1zZXJ2ZXIBAgMEBQYH\n-----END OPENSSH PRIVATE KEY-----\n";

const USER: &str = "tester";
const PASSWORD: &str = "correct horse";

/// The same sequence every other mock serves.
fn byte_at(offset: u64) -> u8 {
    let mut x = (offset as u32).wrapping_add(0x9e37_79b9);
    x = (x ^ (x >> 16)).wrapping_mul(0x85eb_ca6b);
    x = (x ^ (x >> 13)).wrapping_mul(0xc2b2_ae35);
    x ^= x >> 16;
    (x & 0xff) as u8
}

/// `/file-<n>.bin` is a file of n bytes.
fn size_of(path: &str) -> Option<u64> {
    let name = path.rsplit('/').next()?;
    let digits = name.strip_prefix("file-")?.strip_suffix(".bin")?;
    digits.parse().ok()
}

// ---------------------------------------------------------------------------
// SFTP
// ---------------------------------------------------------------------------

#[derive(Default)]
struct SftpHandler {
    /// Handle to the path it was opened for.
    open_files: HashMap<String, String>,
    next_handle: u64,
}

impl russh_sftp::server::Handler for SftpHandler {
    type Error = StatusCode;

    fn unimplemented(&self) -> Self::Error {
        StatusCode::OpUnsupported
    }

    async fn init(
        &mut self,
        _version: u32,
        _extensions: HashMap<String, String>,
    ) -> Result<Version, Self::Error> {
        Ok(Version::new())
    }

    async fn realpath(&mut self, id: u32, path: String) -> Result<Name, Self::Error> {
        // Enough to satisfy a client that canonicalises before opening.
        let resolved = if path == "." { "/".to_owned() } else { path };
        Ok(Name { id, files: vec![File::dummy(&resolved)] })
    }

    async fn stat(&mut self, id: u32, path: String) -> Result<Attrs, Self::Error> {
        let size = size_of(&path).ok_or(StatusCode::NoSuchFile)?;
        Ok(Attrs { id, attrs: FileAttributes { size: Some(size), ..Default::default() } })
    }

    async fn lstat(&mut self, id: u32, path: String) -> Result<Attrs, Self::Error> {
        self.stat(id, path).await
    }

    async fn open(
        &mut self,
        id: u32,
        filename: String,
        _flags: OpenFlags,
        _attrs: FileAttributes,
    ) -> Result<Handle, Self::Error> {
        if size_of(&filename).is_none() {
            return Err(StatusCode::NoSuchFile);
        }
        self.next_handle += 1;
        let handle = format!("h{}", self.next_handle);
        self.open_files.insert(handle.clone(), filename);
        Ok(Handle { id, handle })
    }

    async fn read(
        &mut self,
        id: u32,
        handle: String,
        offset: u64,
        len: u32,
    ) -> Result<Data, Self::Error> {
        let path = self.open_files.get(&handle).ok_or(StatusCode::Failure)?;
        let total = size_of(path).ok_or(StatusCode::NoSuchFile)?;

        if offset >= total {
            // How SFTP says "end of file", rather than an empty read.
            return Err(StatusCode::Eof);
        }
        let end = (offset + len as u64).min(total);
        let data = (offset..end).map(byte_at).collect();
        Ok(Data { id, data })
    }

    async fn close(&mut self, id: u32, handle: String) -> Result<Status, Self::Error> {
        self.open_files.remove(&handle);
        Ok(Status {
            id,
            status_code: StatusCode::Ok,
            error_message: "ok".to_owned(),
            language_tag: "en-US".to_owned(),
        })
    }
}

// ---------------------------------------------------------------------------
// SSH
// ---------------------------------------------------------------------------

struct Server;

impl russh::server::Server for Server {
    type Handler = SshHandler;

    fn new_client(&mut self, _peer: Option<std::net::SocketAddr>) -> SshHandler {
        SshHandler { channel: None }
    }
}

struct SshHandler {
    channel: Option<Channel<Msg>>,
}

impl russh::server::Handler for SshHandler {
    type Error = russh::Error;

    async fn auth_password(&mut self, user: &str, password: &str) -> Result<Auth, Self::Error> {
        if user == USER && password == PASSWORD {
            Ok(Auth::Accept)
        } else {
            Ok(Auth::Reject { proceed_with_methods: None, partial_success: false })
        }
    }

    /// Accepts any key offered.
    ///
    /// This is a test server on localhost; the question it exists to answer
    /// is whether the client finds a key, offers it and proceeds, not
    /// whether this server can tell one key from another. Checking a real
    /// authorized_keys would mean generating a matching pair for every run
    /// and testing russh's signature verification rather than our own code.
    async fn auth_publickey(
        &mut self,
        user: &str,
        _key: &russh::keys::PublicKey,
    ) -> Result<Auth, Self::Error> {
        if user == USER {
            Ok(Auth::Accept)
        } else {
            Ok(Auth::Reject { proceed_with_methods: None, partial_success: false })
        }
    }

    async fn channel_open_session(
        &mut self,
        channel: Channel<Msg>,
        reply: russh::server::ChannelOpenHandle,
        _session: &mut Session,
    ) -> Result<(), Self::Error> {
        reply.accept().await;
        self.channel = Some(channel);
        Ok(())
    }

    async fn subsystem_request(
        &mut self,
        channel_id: ChannelId,
        name: &str,
        session: &mut Session,
    ) -> Result<(), Self::Error> {
        if name != "sftp" {
            session.channel_failure(channel_id)?;
            return Ok(());
        }

        let Some(channel) = self.channel.take() else {
            session.channel_failure(channel_id)?;
            return Ok(());
        };
        session.channel_success(channel_id)?;

        tokio::spawn(async move {
            russh_sftp::server::run(channel.into_stream(), SftpHandler::default()).await;
        });
        Ok(())
    }
}

#[tokio::main]
async fn main() {
    let arguments: Vec<String> = std::env::args().collect();
    let value = |name: &str| {
        arguments.iter().position(|a| a == name).and_then(|i| arguments.get(i + 1)).cloned()
    };

    let port: u16 = value("--port").and_then(|p| p.parse().ok()).unwrap_or(2222);

    // A fixed key, not a fresh one. This server only ever listens on
    // localhost for a test, so there is nothing to protect — and a key that
    // never changes means a test can write it into a known_hosts file and
    // check what happens when it matches, when it is absent, and when it has
    // been replaced. A key generated per run could only ever test the
    // absent case.
    let key = PrivateKey::from_openssh(HOST_KEY).expect("the built-in host key");

    if let Some(path) = value("--host-key") {
        // Written in the form known_hosts uses, so a test can build one.
        let public = key.public_key().to_openssh().expect("the public key");
        std::fs::write(&path, format!("{public}\n")).expect("writing the host key");
    }

    let config = Arc::new(russh::server::Config {
        inactivity_timeout: Some(std::time::Duration::from_secs(60)),
        auth_rejection_time: std::time::Duration::from_millis(100),
        methods: MethodSet::from(&[russh::MethodKind::Password, russh::MethodKind::PublicKey][..]),
        keys: vec![key],
        ..Default::default()
    });

    println!("sftp-server listening on port {port}");
    Server.run_on_address(config, ("127.0.0.1", port)).await.expect("the server should run");
}
